/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-attributes.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below, the
 * `useItemVariant` import path rewrite (see next paragraph), and a temporary `[overrides]`
 * console.log marker (verified live, then removed). The `<Stack spacing={1.5} flex={1} {...props}>` defaults-then-spread prop
 * order is preserved exactly, unchanged from base.
 *
 * The base file imports `useItemVariant` from the SFCC package path
 * (`@salesforce/retail-react-app/app/components/item-variant`) — inconsistent with its own three
 * siblings (item-image/item-name/item-price), which all already import it via the relative `'.'`.
 * Since `item-variant/index.tsx` is itself being overridden in this same commit,
 * this import is rewritten to match its siblings (`'.'`) per
 * .claude/rules/overrideStyling.md's "Importing an already-overridden component from a new
 * component" — a base-path import here would silently exercise the base `useItemVariant`/context
 * in Storybook and Vitest instead of this override.
 *
 * `useCurrentBasket` (from the SFCC hooks path) and the `useCurrency`/`app/hooks` barrel are not
 * overridden anywhere in this repo (verified by directory listing at time of writing — no
 * overrides/app/hooks/use-current-basket.ts, no overrides/app/hooks/index.ts), so both stay on
 * the base `@salesforce/retail-react-app/...` path.
 *
 * SFCC-270 (plan step 2.2): adds `combineAttributeValues`, used by product-item/index.tsx to
 * render the Figma cart-item spec's colour+size string ("Lilac Sand, One size") as a single
 * combined <Text>, instead of this file's existing per-key behaviour (one <Text> per
 * variation-value key, with or without its label per `hideAttributeLabels`) — a genuinely
 * different rendering shape, not just `hideAttributeLabels` with the label omitted, since that
 * flag still produces one <Text> per key. Defaults to `false`, so the existing per-key
 * behaviour (and every other branch in this file — bonus label, quantity, bundles, promotions)
 * is unchanged for any caller that doesn't pass it.
 */
import React from 'react';
import { useIntl, FormattedMessage, FormattedNumber } from 'react-intl';
import { Flex, Stack, Text, Box, useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover';
import { useCurrency } from '@salesforce/retail-react-app/app/hooks';
import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
import { usePromotions, useProducts, useProduct } from '@salesforce/commerce-sdk-react';
import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

type ItemAttributesProps = {
  includeQuantity?: boolean;
  currency?: string;
  excludeBonusLabel?: boolean;
  hideAttributeLabels?: boolean;
  /** See this file's own SFCC-270 docblock note above. */
  combineAttributeValues?: boolean;
} & Record<string, any>;

/**
 * In the context of a cart product item variant, this component renders a styled
 * list of the selected variation values as well as any promos (w/ info popover).
 */
const ItemAttributes = ({
  includeQuantity,
  currency,
  excludeBonusLabel,
  hideAttributeLabels = false,
  combineAttributeValues = false,
  ...props
}: ItemAttributesProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
  const { data: basket } = useCurrentBasket();
  const { currency: activeCurrency } = useCurrency();
  const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? [];
  const intl = useIntl();

  const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem;

  // Fetch all the promotions given by price adjustments. We display this info in
  // the promotion info popover when applicable.
  const { data: res } = usePromotions(
    {
      parameters: {
        ids: promotionIds.join(','),
      },
    },
    {
      enabled: promotionIds.length > 0,
    },
  );
  const promos = res?.data || [];
  const variationValues = getDisplayVariationValues(variant?.variationAttributes, variant?.variationValues);

  // get variant info for bundled products in cart page and order history page
  const productBundleIds = variant?.bundledProductItems?.map(({ productId }: SfccVariant) => productId).join(',') ?? '';
  const { data: productBundleVariantData, isLoading: bundleVariantIsLoading } = useProducts(
    {
      parameters: {
        ids: productBundleIds,
        allImages: false,
      },
    },
    {
      enabled: Boolean(variant?.type?.bundle && productBundleIds),
      select: (result: SfccVariant) => {
        // formats response so we can easily display child quantity/variant selection
        return result?.data?.map((item: SfccVariant) => {
          const quantity = variant?.bundledProductItems.find(
            (childProduct: SfccVariant) => childProduct.productId === item.id,
          )?.quantity;
          return {
            ...item,
            quantity,
            variationValues: getDisplayVariationValues(item?.variationAttributes, item?.variationValues),
          };
        });
      },
    },
  );

  // get bundle product data for wishlist page
  const { data: productBundleData, isLoading: productBundleIsLoading } = useProduct(
    {
      parameters: {
        id: variant?.id,
        allImages: false,
      },
    },
    {
      enabled: Boolean(variant?.type?.bundle && !productBundleIds),
    },
  );

  return (
    <Stack spacing={1.5} flex={1} {...props}>
      {displayBonusProductLabel && (
        <Text lineHeight={1} color="black.600" fontSize="sm">
          <FormattedMessage defaultMessage="Bonus Product" id="item_attributes.label.bonus_product" />
        </Text>
      )}

      {variationValues && combineAttributeValues && (
        <Text sx={styles.colourSize}>{Object.values(variationValues).join(', ')}</Text>
      )}

      {variationValues &&
        !combineAttributeValues &&
        Object.keys(variationValues).map((key) => (
          <Text lineHeight={1} color="gray.700" fontSize="sm" key={`${key}: ${variationValues[key]}`}>
            {hideAttributeLabels ? variationValues[key] : `${key}: ${variationValues[key]}`}
          </Text>
        ))}

      {includeQuantity && (
        <Text lineHeight={1} color="gray.700" fontSize="sm">
          <FormattedMessage
            defaultMessage="Quantity: {quantity}"
            values={{ quantity: variant.quantity }}
            id="item_attributes.label.quantity"
          />
        </Text>
      )}

      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
        <Box>
          {/* Deviation from the base file (same labelled-comment convention as
                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
                        `bundledProducts` is itself optional on the SDK's real Product type even
                        once `productBundleData` is truthy, which strict null checks catches and
                        the base file's plain JS did not need to guard against. This is a real,
                        narrow behaviour difference from base, not a pure typing satisfier: base
                        would throw here if `bundledProducts` were ever undefined on an otherwise
                        truthy `productBundleData`; this renders nothing instead. Directionally
                        safer (crash -> silent no-render), so left as-is rather than reverted to
                        match base's crash-on-that-shape behaviour exactly. */}
          {productBundleData?.bundledProducts?.map(({ product, quantity }: SfccVariant) => (
            <Box marginTop={2} key={product.id}>
              <Text fontSize="sm" color="gray.700" as="b">
                {product?.name}
              </Text>
              <Text fontSize="sm" color="gray.700">
                {intl.formatMessage({
                  defaultMessage: 'Qty',
                  id: 'add_to_cart_modal.label.quantity',
                })}
                : {quantity}
              </Text>
            </Box>
          ))}
        </Box>
      )}

      {!bundleVariantIsLoading && productBundleVariantData && (
        <Box>
          <Text fontSize={15} marginTop={3} fontWeight={500}>
            {intl.formatMessage({
              defaultMessage: 'Selected Options',
              id: 'item_attributes.label.selected_options',
            })}
            :
          </Text>
          {productBundleVariantData?.map(({ variationValues, name: productName, quantity, id }: SfccVariant) => {
            return (
              <Box key={id} marginTop={2}>
                <Text fontSize="sm" color="gray.700" as="b">
                  {productName}
                </Text>
                <Text fontSize="sm" color="gray.700">
                  {intl.formatMessage({
                    defaultMessage: 'Qty',
                    id: 'add_to_cart_modal.label.quantity',
                  })}
                  : {quantity}
                </Text>
                {Object.keys(variationValues).map((key) => {
                  const selectedVariant = `${key}: ${variationValues[key]}`;
                  return (
                    <Text fontSize="sm" color="gray.700" key={selectedVariant}>
                      {selectedVariant}
                    </Text>
                  );
                })}
              </Box>
            );
          })}
        </Box>
      )}

      {variant.priceAdjustments?.length > 0 && (
        <Flex alignItems="center">
          <Text lineHeight={1} color="gray.700" fontSize="sm">
            <FormattedMessage defaultMessage="Promotions" id="item_attributes.label.promotions" />
            {': '}
            <Text as="span" color="green.700">
              <FormattedNumber
                style="currency"
                currency={currency || basket?.currency || activeCurrency}
                value={variant.priceAdjustments.reduce((acc: number, adj: SfccVariant) => acc + (adj.price ?? 0), 0)}
              />
            </Text>
          </Text>
          <PromoPopover ml={2}>
            <Stack>
              {promos?.map((promo: SfccVariant) => (
                <Text key={promo?.id} fontSize="sm">
                  {promo?.calloutMsg}
                </Text>
              ))}
            </Stack>
          </PromoPopover>
        </Flex>
      )}
    </Stack>
  );
};

export default ItemAttributes;

import { breakpoints } from 'app/theme/foundation';

// Figma "Image" spec (product-item card, SFCC-270): 132x198 desktop, 67x100 mobile — no
// --zimm-scale equivalent exists at either pixel pair.
// audit-allow: Figma-confirmed cart-item image dimensions, no foundation token at this value.
const IMAGE_WIDTH_MOBILE = '67px';
const IMAGE_WIDTH_DESKTOP = '132px';

// Figma "colour + size" caption string: 200px, no --zimm-scale equivalent at this value.
// audit-allow: Figma-confirmed width, no foundation token at this value.
const COLOUR_SIZE_WIDTH = '200px';

/**
 * Co-located recipe for the item-variant family (item-image / item-attributes / item-price).
 * SFCC-270 (plan step 2.2).
 *
 * Parts:
 *   - `image` — item-image.tsx's outer Box: responsive width, ivory-200 background. Applied
 *     via `__css`, not `sx` — this one MUST stay overridable: order-summary/index.jsx (base
 *     SFCC, not yet overridden in this repo) calls
 *     `<CartItemVariantImage width="80px" mr={2} />` and depends on its own caller-supplied
 *     `width` winning over whatever default this component ships. `__css` is the lowest-
 *     priority slot in `@chakra-ui/system`'s `toCSSObject` merge (`chunk-E32MZNBA.mjs`:
 *     `assignAfter({}, __css, baseStyle, styleProps, sx)`), and `Box` carries no competing
 *     baseStyle of its own (`@chakra-ui/layout`'s `chunk-6CSUKJP7.mjs`: `var Box =
 *     chakra("div")`, no options) — confirmed by reading both files, not assumed — so a
 *     literal caller prop always wins over this part's `__css` default.
 *   - `img` — the inner <Image>: responsive objectFit (contain mobile / cover desktop) plus
 *     mix-blend-multiply, so the photo blends against the `image` part's ivory backdrop.
 *     `__css` is safe here too — Chakra's own `Image` (`@chakra-ui/image`'s
 *     `chunk-SMHKDLMK.mjs`) never sets a literal `__css` key of its own, unlike `Text` below.
 *   - `colourSize` — item-attributes.tsx's combined "colour, size" string.
 *   - `price` — item-price.tsx's price Stack (`textStyle: 'price'` only; the actual price
 *     digits render via the base, un-overridden `display-price`/`current-price` components,
 *     which set no competing font-size of their own — confirmed by reading both files — so
 *     the textStyle cascades down via ordinary CSS inheritance without touching either file).
 *
 * `colourSize` and `price` are applied via `sx`, not `__css`: Chakra's own `Text`
 * (`@chakra-ui/layout`'s `chunk-P74GIWPW.mjs`) places its OWN `__css={styles}` (from
 * `useStyleConfig('Text', props)`) as a literal key AFTER `...rest` in its own render call —
 * a caller-supplied `__css` prop would be silently discarded entirely there (a later
 * same-named key in one object literal replaces the earlier one; it does not merge). `sx` is
 * destructured separately by `toCSSObject` and isn't subject to that collision, so it's the
 * reliable way to style a plain `<Text>`/`<Stack>` from outside. Verified by reading the
 * compiled source directly. `price`'s own Stack has no such hazard (`@chakra-ui/layout`'s
 * `chunk-WKZT7ZXJ.mjs` Stack sets no literal `__css` key at all), so either mechanism would
 * have worked there — `sx` is used anyway, for one consistent rule across this file's parts
 * rather than a different mechanism per element.
 */
export const ZimmCartItemVariant = {
  parts: ['image', 'img', 'colourSize', 'price'],
  baseStyle: {
    image: {
      width: IMAGE_WIDTH_MOBILE,
      backgroundColor: 'var(--zimm-color-bg-02)',
      [`@media (min-width: ${breakpoints.md})`]: {
        width: IMAGE_WIDTH_DESKTOP,
      },
    },
    img: {
      objectFit: 'contain',
      mixBlendMode: 'multiply',
      [`@media (min-width: ${breakpoints.md})`]: {
        objectFit: 'cover',
      },
    },
    colourSize: {
      textStyle: 'caption',
      // Figma's colour+size string is the regular-weight "Default/Caption" node; this repo's
      // `caption` textStyle (theme/foundation/typography.ts) is medium-weight, matching the
      // different "Default/Caption-strong" node instead (confirmed: typography.ts's `caption`
      // entry sets `fontWeight: fontWeights.medium`). Overridden here rather than in
      // typography.ts (Tier 1, out of scope for a cart ticket) — same "cite the conflict at
      // the point of divergence" pattern zimmButton.css.ts's `sizes.lg`/`sizes.sm` fontSize
      // comment already uses for a leaked-default conflict of its own.
      fontWeight: 'var(--zimm-font-weight-regular)',
      width: COLOUR_SIZE_WIDTH,
      color: 'var(--zimm-color-text-secondary)',
    },
    price: {
      textStyle: 'price',
    },
  },
};

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-image.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at that step beyond the TypeScript annotations and a
 * temporary `[overrides]` console.log marker (verified live, then removed).
 *
 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec. The outer Box's own literal
 * `width="84px" backgroundColor="gray.100"` defaults are gone, replaced by item-variant.css.ts's
 * `image` part via `__css` — kept as `__css`, not `sx`, specifically so a caller-supplied
 * `width`/`mr` (e.g. order-summary/index.jsx's base, not-yet-overridden
 * `<CartItemVariantImage width="80px" mr={2} />`) still wins; see that recipe's own docblock for
 * why. `{...props}` stays spread last, same defaults-then-spread order as before, still what
 * lets that caller-supplied width win. `ratio`'s default changed from `1` to the Figma-confirmed
 * 288/432 cart-item image ratio; the inner <Image> now also carries the `img` part's responsive
 * objectFit + mix-blend-multiply. Badge styling (Sale/Unavailable) is untouched — no Figma value
 * was given for it at this step.
 */
import React from 'react';
import {
  AspectRatio,
  Box,
  Badge,
  Image,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import { FormattedMessage } from 'react-intl';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

type ItemImageProps = {
  imageProps?: Record<string, any>;
  ratio?: number;
} & Record<string, any>;

const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

// Figma "Image" spec, product-item card (SFCC-270): aspect ratio 288/432, which reduces to 2/3
// exactly. Matches the design record's own 132x198 desktop pair exactly (132 * 432/288 = 198);
// against the 67x100 mobile pair it lands at 100.5 — half a pixel over the stated 100, the same
// class of Figma-rounding gap zimmDrawer.css.ts's WIDTH_XLARGE note already documents for a
// different value, not something introduced here.
const CART_ITEM_IMAGE_RATIO = 288 / 432;

/**
 * In the context of a cart product item variant, this component renders the item's
 * main image.
 *
 * @todo = This component will render a `SALE` badge when the qualifier is available
 * on the custom property `c_isSale`. This will need to be expanded upon to handle
 * different badge/qualifiers and property names.
 */
const ItemImage = ({ imageProps, ratio = CART_ITEM_IMAGE_RATIO, ...props }: ItemImageProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});

  // We find the 'small' images in the variant's image groups based on variationValues and pick the first one
  const image = findImageGroupBy(variant?.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: variant?.variationValues,
  })?.images?.[0];

  return (
    <Box __css={styles.image} {...props}>
      <AspectRatio ratio={ratio}>
        <Box position="relative">
          {variant.c_isSale && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="blue"
            >
              <FormattedMessage
                defaultMessage="Sale"
                id="item_image.label.sale"
                description="A sale badge placed on top of a product image"
              />
            </Badge>
          )}
          {variant.isProductUnavailable && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="red"
            >
              <FormattedMessage
                defaultMessage="Unavailable"
                id="item_image.label.unavailable"
                description="A unavailable badge placed on top of a product image"
              />
            </Badge>
          )}

          {image && (
            <Image
              alt={image.alt}
              src={`${image.disBaseLink || image.link}`}
              ignoreFallback={true}
              __css={styles.img}
              {...imageProps}
            />
          )}
        </Box>
      </AspectRatio>
    </Box>
  );
};

export default ItemImage;

