10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond: the TypeScript annotations below, an explicit
12	 * `undefined` default value passed to `createContext` (React's TS types require this parameter;
13	 * the base file's argument-less `createContext()` call is only legal in untyped JS, where an
14	 * omitted argument is implicitly `undefined` at runtime too — same value, just spelled out so it
15	 * type-checks), and a temporary `[overrides]` console.log marker (verified live, then removed).
16	 * Styling/behaviour changes are a later commit (2.2), not this one.
17	 *
18	 * `SfccVariant` is kept as `any` with a named alias rather than a structural type invented from
19	 * usage — this package ships no TypeScript types for this shape, matching the same documented gap
20	 * at overrides/app/components/product-view/index.tsx:136-151.
21	 */
22	import React, { createContext, useContext } from 'react';
23	
24	/**
25	 * This component and associated context/hook provide a convenient wrapper
26	 * around a group of components used for rendering product variant details.
27	 */
28	
29	type SfccVariant = any;
30	
31	const ItemVariantContext = createContext<SfccVariant>(undefined);
32	
33	export const useItemVariant = (): SfccVariant => {
34	  return useContext(ItemVariantContext);
35	};
36	
37	type ItemVariantProviderProps = {
38	  variant?: SfccVariant;
39	  children?: React.ReactNode;
40	};
41	
42	/**
43	 * The Provider component for rendering product item and variant detail.
44	 */
45	const ItemVariantProvider = ({ variant, children }: ItemVariantProviderProps) => {
46	  return <ItemVariantContext.Provider value={variant}>{children}</ItemVariantContext.Provider>;
47	};
48	
49	export default ItemVariantProvider;

